package com.sobrenaturaldirector.narrative;
import java.util.*;import java.security.*;import net.minecraft.nbt.*;import com.sobrenaturaldirector.capability.*;import com.sobrenaturaldirector.content.model.SemanticCapability;import com.sobrenaturaldirector.domain.StableId;import com.sobrenaturaldirector.environment.model.EnvironmentClassification;import com.sobrenaturaldirector.planning.environment.EnvironmentActionImpact;
/** Durable semantic plan record; it contains no entity UUID and never executes. */
public final class PersistentNarrativePlan{
 public static final int SCHEMA_VERSION=1,MAX_REPLANS=8;private final String id,narrativeId,intent,blueprintId,blueprintFingerprint,planFingerprint,candidateSignature,relation;private String threadId="";private final boolean continuation;private final EnvironmentActionImpact impact;private final Map<String,CapabilityRecord> capabilities;private final NarrativePlanLifecycleState state;private final long createdTick,updatedTick,expiryTick,lastValidatedTick;private final String validationStatus,parentPlanId;private final List<String> validationReasons;private final int replanCount,providerRevision,dimension,regionX,regionZ;private final EnvironmentClassification environment;private final int environmentConfidence,recentActivity;
 public PersistentNarrativePlan(String id,String narrativeId,String intent,String blueprintId,String blueprintFingerprint,String planFingerprint,String candidateSignature,String relation,EnvironmentActionImpact impact,Map<String,CapabilityRecord> capabilities,boolean continuation,NarrativePlanLifecycleState state,long createdTick,long updatedTick,long expiryTick,long lastValidatedTick,String validationStatus,List<String> validationReasons,String parentPlanId,int replanCount,int providerRevision,int dimension,int regionX,int regionZ,EnvironmentClassification environment,int environmentConfidence,int recentActivity){this.id=req(id);this.narrativeId=text(narrativeId);this.intent=req(intent);this.blueprintId=req(blueprintId);this.blueprintFingerprint=req(blueprintFingerprint);this.planFingerprint=text(planFingerprint);this.candidateSignature=text(candidateSignature);this.relation=text(relation);if(impact==null||state==null||environment==null||replanCount<0||replanCount>MAX_REPLANS||providerRevision<0||environmentConfidence<0||environmentConfidence>100||recentActivity<0||recentActivity>100)throw new IllegalArgumentException("invalid narrative plan");Map<String,CapabilityRecord> copy=new TreeMap<String,CapabilityRecord>(capabilities==null?Collections.<String,CapabilityRecord>emptyMap():capabilities);for(Map.Entry<String,CapabilityRecord> e:copy.entrySet())if(e.getValue()==null)throw new IllegalArgumentException("null capability");this.impact=impact;this.capabilities=Collections.unmodifiableMap(copy);this.continuation=continuation;this.state=state;this.createdTick=createdTick;this.updatedTick=updatedTick;this.expiryTick=expiryTick;this.lastValidatedTick=lastValidatedTick;this.validationStatus=text(validationStatus);this.validationReasons=Collections.unmodifiableList(new ArrayList<String>(validationReasons==null?Collections.<String>emptyList():validationReasons));this.parentPlanId=text(parentPlanId);this.replanCount=replanCount;this.providerRevision=providerRevision;this.dimension=dimension;this.regionX=regionX;this.regionZ=regionZ;this.environment=environment;this.environmentConfidence=environmentConfidence;this.recentActivity=recentActivity;}
 public static PersistentNarrativePlan fromSynthesis(String id,NarrativePlanSynthesisResult r,long tick,long expiry,int revision){if(r==null||!r.isSynthesized()||r.getCandidatePlan()==null||r.getBlueprint()==null)throw new IllegalArgumentException("synthesized result required");Map<String,CapabilityRecord> m=new LinkedHashMap<String,CapabilityRecord>();for(Map.Entry<SemanticCapability,CapabilityDescriptor> e:r.getSelections().entrySet())m.put(e.getKey().getValue(),new CapabilityRecord(e.getValue().getProvider().getValue(),e.getValue().getAvailability(),e.getValue().getPriority(),e.getValue().getCost()));com.sobrenaturaldirector.situation.SituationContext c=r.getRequest().getSituation();com.sobrenaturaldirector.environment.model.SemanticRegionProfile p=c.getRegionProfile();return new PersistentNarrativePlan(id,r.getRequest().getNarrativeId(),r.getRequest().getIntent().name(),r.getBlueprint().getId(),compact(r.getBlueprint().fingerprint()),compact(r.getPlanFingerprint()),compact(r.getCandidatePlan().signature()),r.getRegionRelation(),r.getImpact(),m,r.getRequest().isContinuation(),NarrativePlanLifecycleState.PROPOSED,tick,tick,expiry,-1,"UNVALIDATED",r.getReasons(),"",0,revision,c.getDimension(),c.getRegionX(),c.getRegionZ(),p==null?EnvironmentClassification.UNKNOWN:p.getClassification(),p==null?0:p.getConfidence(),p==null?0:p.getRecentActivity()).withThreadId(r.getRequest().getThreadId());}
 private static String compact(String v){if(v==null||v.length()<=StableId.MAX_LENGTH)return v==null?"":v;try{byte[] d=MessageDigest.getInstance("SHA-256").digest(v.getBytes("UTF-8"));StringBuilder b=new StringBuilder("sha256:");for(byte x:d)b.append(String.format("%02x",x&255));return b.toString();}catch(Exception e){throw new IllegalStateException(e);}}
 private static String req(String v){return StableId.require(v,"plan");}private static String text(String v){if(v==null)return"";if(v.length()>128)throw new IllegalArgumentException("plan text too long");return v;}
 public String getId(){return id;}public String getNarrativeId(){return narrativeId;}public String getThreadId(){return threadId;}public String getIntent(){return intent;}public String getBlueprintId(){return blueprintId;}public String getBlueprintFingerprint(){return blueprintFingerprint;}public String getPlanFingerprint(){return planFingerprint;}public String getCandidateSignature(){return candidateSignature;}public String getRegionRelation(){return relation;}public EnvironmentActionImpact getImpact(){return impact;}public boolean isContinuation(){return continuation;}public Map<String,CapabilityRecord> getCapabilities(){return capabilities;}public NarrativePlanLifecycleState getState(){return state;}public long getCreatedTick(){return createdTick;}public long getUpdatedTick(){return updatedTick;}public long getExpiryTick(){return expiryTick;}public long getLastValidatedTick(){return lastValidatedTick;}public String getValidationStatus(){return validationStatus;}public List<String> getValidationReasons(){return validationReasons;}public String getParentPlanId(){return parentPlanId;}public int getReplanCount(){return replanCount;}public int getProviderRevision(){return providerRevision;}public int getDimension(){return dimension;}public int getRegionX(){return regionX;}public int getRegionZ(){return regionZ;}public EnvironmentClassification getEnvironment(){return environment;}public int getEnvironmentConfidence(){return environmentConfidence;}public int getRecentActivity(){return recentActivity;}
 public PersistentNarrativePlan withThreadId(String value){PersistentNarrativePlan r=copy(state,updatedTick,lastValidatedTick,validationStatus,validationReasons,parentPlanId,replanCount);r.threadId=text(value);return r;}public PersistentNarrativePlan withState(NarrativePlanLifecycleState next,long tick){if(next==null||(state.isTerminal()&&next!=state))throw new IllegalStateException("terminal plan cannot transition");return copy(next,tick,lastValidatedTick,validationStatus,validationReasons,parentPlanId,replanCount);}public PersistentNarrativePlan validated(String status,List<String> reasons,long tick,NarrativePlanLifecycleState next){return copy(next,tick,tick,status,reasons,parentPlanId,replanCount);}public PersistentNarrativePlan supersededBy(String replacement,long tick){return copy(NarrativePlanLifecycleState.SUPERSEDED,tick,lastValidatedTick,"SUPERSEDED",Collections.singletonList("SUPERSEDED_BY:"+replacement),replacement,replanCount);}
 private PersistentNarrativePlan copy(NarrativePlanLifecycleState next,long tick,long valid,String status,List<String> reasons,String parent,int count){PersistentNarrativePlan r=new PersistentNarrativePlan(id,narrativeId,intent,blueprintId,blueprintFingerprint,planFingerprint,candidateSignature,relation,impact,capabilities,continuation,next,createdTick,tick,expiryTick,valid,status,reasons,parent,count,providerRevision,dimension,regionX,regionZ,environment,environmentConfidence,recentActivity);r.threadId=threadId;return r;}
 public NBTTagCompound toNbt(){NBTTagCompound n=new NBTTagCompound();n.setInteger("schemaVersion",SCHEMA_VERSION);n.setString("id",id);if(threadId.length()>0)n.setString("threadId",threadId);n.setString("narrativeId",narrativeId);n.setString("intent",intent);n.setString("blueprintId",blueprintId);n.setString("blueprintFingerprint",blueprintFingerprint);n.setString("planFingerprint",planFingerprint);n.setString("candidateSignature",candidateSignature);n.setString("relation",relation);n.setString("impact",impact.name());n.setBoolean("continuation",continuation);n.setString("state",state.name());n.setLong("createdTick",createdTick);n.setLong("updatedTick",updatedTick);n.setLong("expiryTick",expiryTick);n.setLong("lastValidatedTick",lastValidatedTick);n.setString("validationStatus",validationStatus);n.setString("parentPlanId",parentPlanId);n.setInteger("replanCount",replanCount);n.setInteger("providerRevision",providerRevision);n.setInteger("dimension",dimension);n.setInteger("regionX",regionX);n.setInteger("regionZ",regionZ);n.setString("environment",environment.name());n.setInteger("environmentConfidence",environmentConfidence);n.setInteger("recentActivity",recentActivity);NBTTagList cs=new NBTTagList();for(Map.Entry<String,CapabilityRecord> e:capabilities.entrySet()){NBTTagCompound c=e.getValue().toNbt();c.setString("capability",e.getKey());cs.appendTag(c);}n.setTag("capabilities",cs);NBTTagList rs=new NBTTagList();for(String v:validationReasons){NBTTagCompound r=new NBTTagCompound();r.setString("value",v);rs.appendTag(r);}n.setTag("validationReasons",rs);return n;}
 public static PersistentNarrativePlan fromNbt(NBTTagCompound n){if(n==null||n.getInteger("schemaVersion")!=SCHEMA_VERSION||!n.hasKey("capabilities",9)||!n.hasKey("validationReasons",9))throw new IllegalArgumentException("invalid narrative plan schema");Map<String,CapabilityRecord> c=new LinkedHashMap<String,CapabilityRecord>();NBTTagList cs=n.getTagList("capabilities",10);if(cs.tagCount()>64)throw new IllegalArgumentException("capability limit");for(int i=0;i<cs.tagCount();i++){NBTTagCompound x=cs.getCompoundTagAt(i);c.put(x.getString("capability"),CapabilityRecord.fromNbt(x));}List<String> rs=new ArrayList<String>();NBTTagList rl=n.getTagList("validationReasons",10);for(int i=0;i<rl.tagCount();i++)rs.add(rl.getCompoundTagAt(i).getString("value"));PersistentNarrativePlan r=new PersistentNarrativePlan(n.getString("id"),n.getString("narrativeId"),n.getString("intent"),n.getString("blueprintId"),n.getString("blueprintFingerprint"),n.getString("planFingerprint"),n.getString("candidateSignature"),n.getString("relation"),EnvironmentActionImpact.valueOf(n.getString("impact")),c,n.getBoolean("continuation"),NarrativePlanLifecycleState.valueOf(n.getString("state")),n.getLong("createdTick"),n.getLong("updatedTick"),n.getLong("expiryTick"),n.getLong("lastValidatedTick"),n.getString("validationStatus"),rs,n.getString("parentPlanId"),n.getInteger("replanCount"),n.getInteger("providerRevision"),n.getInteger("dimension"),n.getInteger("regionX"),n.getInteger("regionZ"),EnvironmentClassification.valueOf(n.getString("environment")),n.getInteger("environmentConfidence"),n.getInteger("recentActivity"));r.threadId=text(n.getString("threadId"));return r;}
 public static final class CapabilityRecord{private final String provider;private final ProviderAvailability availability;private final int priority,cost;public CapabilityRecord(String p,ProviderAvailability a,int priority,int cost){provider=req(p);if(a==null||priority<0||cost<0)throw new IllegalArgumentException("invalid capability");availability=a;this.priority=priority;this.cost=cost;}public String getProvider(){return provider;}public ProviderAvailability getAvailability(){return availability;}public int getPriority(){return priority;}public int getCost(){return cost;}private NBTTagCompound toNbt(){NBTTagCompound n=new NBTTagCompound();n.setString("provider",provider);n.setString("availability",availability.name());n.setInteger("priority",priority);n.setInteger("cost",cost);return n;}private static CapabilityRecord fromNbt(NBTTagCompound n){return new CapabilityRecord(n.getString("provider"),ProviderAvailability.valueOf(n.getString("availability")),n.getInteger("priority"),n.getInteger("cost"));}}
}
